func label(l ast.Label) string {
	switch v := l.(type) {
	case *ast.Ident:
		return v.Name
	case *ast.BasicLit:
		return v.Value
	case nil:
		return "<nil>"
	default:
		return fmt.Sprintf("<%T>", v)
