func indent(d int) string { return strings.Repeat("  ", d) }

func printField(fld *ast.Field, d int) {
	fmt.Printf("%sField label=%q attrs=%d value=%T\n", indent(d), label(fld.Label), len(fld.Attrs), fld.Value)
	for _, a := range fld.Attrs {
		fmt.Printf("%s  attr text=%q\n", indent(d), a.Text)
	}
	if sl, ok := fld.Value.(*ast.StructLit); ok {
		for _, e := range sl.Elts {
			printDecl(e, d+1)
		}
	}
}

func printDecl(e ast.Decl, d int) {
	switch v := e.(type) {
	case *ast.Field:
		printField(v, d)
	default:
		fmt.Printf("%s%T\n", indent(d), e)
		if c, ok := e.(*ast.Comprehension); ok {
			fmt.Printf("%s  compValue=%T\n", indent(d), c.Value)
			if sl, ok := c.Value.(*ast.StructLit); ok {
				for _, el := range sl.Elts {
					printDecl(el, d+2)
				}
			}
		}
	}
}

