func StringifyStructLitAsCueString(structLit *ast.StructLit) (*ast.BasicLit, error) {
	return stringifyStructLit(structLit, nil)
}

// stringifyStructLit converts a StructLit to a CUE raw string literal, optionally
// prepending the given comment lines inside the stringified content. The comment
// lines are used to embed field attributes as "// cue-attr:@name(args)" sentinels
// so that validation-exemption intent survives a YAML storage round-trip.
func stringifyStructLit(structLit *ast.StructLit, commentLines []string) (*ast.BasicLit, error) {
	var body string
	if len(structLit.Elts) > 0 {
		formatted, err := format.Node(structLit)
		if err != nil {
			return nil, fmt.Errorf("failed to format struct: %w", err)
		}

		content := strings.TrimSpace(string(formatted))
		if strings.HasPrefix(content, "{") && strings.HasSuffix(content, "}") {
			content = strings.TrimPrefix(content, "{")
			content = strings.TrimSuffix(content, "}")
			content = strings.Trim(content, "\n")
		}
		body = content
	}

	if body == "" && len(commentLines) == 0 {
		return &ast.BasicLit{
			Kind:  token.STRING,
			Value: `"{}"`,
		}, nil
	}

	return wrapCueRawString(commentLines, body), nil
}

// wrapCueRawString wraps comment lines and a struct body into a CUE raw string
// literal (#"""..."""#). Comment lines are emitted before the body content.
func wrapCueRawString(commentLines []string, body string) *ast.BasicLit {
	var lines []string
	lines = append(lines, commentLines...)

	body = strings.Trim(body, "\n")
	if strings.TrimSpace(body) != "" {
		lines = append(lines, strings.Split(body, "\n")...)
	}

	if len(lines) == 0 {
		return &ast.BasicLit{
			Kind:  token.STRING,
			Value: `"{}"`,
		}
	}

	var sb strings.Builder
	sb.WriteString(`#"""`)
	sb.WriteString("\n")
	sb.WriteString(strings.Join(lines, "\n"))
	sb.WriteString("\n")
	sb.WriteString(`"""#`)

	result := strings.ReplaceAll(sb.String(), "\t", "  ")

	return &ast.BasicLit{
		Kind:  token.STRING,
		Value: result,
	}
}

// unwrapCueRawString strips the CUE raw/quoted string markers from a literal value,
// returning the inner content without applying escape-sequence normalization.
func unwrapCueRawString(s string) string {
	s = strings.TrimSpace(s)
	switch {
	case strings.HasPrefix(s, `#"""`) && strings.HasSuffix(s, `"""#`):
		return strings.Trim(strings.TrimSuffix(strings.TrimPrefix(s, `#"""`), `"""#`), "\n")
	case strings.HasPrefix(s, `"""`) && strings.HasSuffix(s, `"""`):
		return strings.Trim(strings.TrimSuffix(strings.TrimPrefix(s, `"""`), `"""`), "\n")
	default:
		if unquoted, err := strconv.Unquote(s); err == nil {
			return unquoted
		}
		return s
	}
