			// Root-level for-comprehensions (e.g. generating dynamic string keys
			// from list data) are supported as long as the generated values are
			// scalars rather than structs.
			if err := validateStatusComprehension(e); err != nil {
				return err
			}

		case *ast.LetClause, *ast.EmbedDecl, *ast.Alias, *ast.Ellipsis:
			// Locally-defined variables and embeddings are permitted at the root.
			continue

		default:
			return fmt.Errorf("status.details contains non-field element")
		}
	}
	return nil
}

// validateStatusValue verifies that a status.details field value is one of the
// supported scalar-producing expression types.
func validateStatusValue(label string, value ast.Expr) error {
	switch value.(type) {
	case *ast.BasicLit,
		*ast.Ident,
		*ast.SelectorExpr,
		*ast.CallExpr,
		*ast.BinaryExpr,
		*ast.UnaryExpr:
		return nil
	default:
		return fmt.Errorf("status.details field %q contains unsupported expression type %T", label, value)
	}
}

// validateStatusComprehension validates a root-level for-comprehension in
// status.details. Comprehensions that generate dynamic string keys are allowed,
// but the generated value for each dynamic key must be a scalar. If the generated
// value is a struct, an error identifying the dynamic label is returned.
func validateStatusComprehension(comp *ast.Comprehension) error {
	structLit, ok := comp.Value.(*ast.StructLit)
	if !ok {
		return nil
	}

	for _, elt := range structLit.Elts {
		switch e := elt.(type) {
		case *ast.Field:
			label := GetFieldLabel(e.Label)
			if label == "" {
				// Dynamically generated labels (e.g. interpolations) have no
				// static name.
				label = dynamicLabelPlaceholder
			}
			if strings.HasPrefix(label, localFieldPrefix) {
				continue
			}
			if _, isStruct := e.Value.(*ast.StructLit); isStruct {
				return fmt.Errorf("status.details field %q generates a struct value; dynamic keys must map to scalar values", label)
