			switch e.Value.(type) {
			case *ast.BasicLit,
				*ast.Ident,
				*ast.SelectorExpr,
				*ast.CallExpr,
				*ast.BinaryExpr,
				*ast.UnaryExpr,
				*ast.Interpolation,
				*ast.IndexExpr:
				continue
			default:
				return fmt.Errorf("status.details field %q contains unsupported expression type %T", label, e.Value)
			}

		case *ast.Comprehension:
			if err := validateStatusComprehension(e); err != nil {
				return err
			}

		default:
			continue
		}
	}
	return nil
