// hasDisableValidation reports whether the given field carries a
// @disableValidation() attribute. It correctly handles fields with no attributes
// as well as fields with multiple attributes.
func hasDisableValidation(field *ast.Field) bool {
	if field == nil {
		return false
	}
	for _, attr := range field.Attrs {
		if attr == nil {
			continue
		}
		key, _ := attr.Split()
		if key == disableValidationAttr {
			return true
		}
	}
	return false
}

// attrSentinelLines converts a field's attributes into "// cue-attr:@name(args)"
// comment lines.
func attrSentinelLines(attrs []*ast.Attribute) []string {
	lines := make([]string, 0, len(attrs))
	for _, attr := range attrs {
		if attr == nil || attr.Text == "" {
			continue
		}
		lines = append(lines, cueAttrSentinelPrefix+attr.Text)
	}
	return lines
}

// extractSentinelAttrs scans a stringified field value for embedded
// "// cue-attr:@name(args)" sentinel comment lines and reconstructs the
// corresponding attributes.
func extractSentinelAttrs(value string) []*ast.Attribute {
	var attrs []*ast.Attribute
	for _, line := range strings.Split(value, "\n") {
		trimmed := strings.TrimSpace(line)
		if !strings.HasPrefix(trimmed, cueAttrSentinelPrefix) {
			continue
		}
		text := strings.TrimSpace(strings.TrimPrefix(trimmed, cueAttrSentinelPrefix))
		if text == "" {
			continue
		}
		attrs = append(attrs, &ast.Attribute{Text: text})
	}
	return attrs
}

