func valStr(rf *ast.Field, path string) string {
	fld, ok := astpkg.GetFieldByPath(rf, path)
	if !ok {
		return "<not found>"
	}
	if bl, ok := fld.Value.(*ast.BasicLit); ok {
		return bl.Value
	}
	return fmt.Sprintf("<%T>", fld.Value)
}

func attrs(rf *ast.Field, path string) []string {
	fld, _ := astpkg.GetFieldByPath(rf, path)
	var out []string
	for _, a := range fld.Attrs {
		out = append(out, a.Text)
	}
	return out
}

